JS=r'''<script id="maxess-nitro-aaa-js">(function(){'use strict';var root=document.getElementById('maxess-results-10');if(!root)return;var NAYA='__NAYA__';var done=false;function r(){return window.MAXESS_RESULT&&typeof window.MAXESS_RESULT==='object'?window.MAXESS_RESULT:null}function c(n){return Math.max(0,Math.min(100,Number(n)||0))}function d(x){return(Array.isArray(x&&x.dimensions)?x.dimensions:[]).slice(0,5).map(function(v){return{name:String(v.name||''),score:c(v.score)}})}function col(s){var a=[[0,255,87,87],[49,255,147,79],[64,255,211,90],[74,84,217,139],[84,56,215,192],[89,67,168,255],[94,155,99,255],[100,237,92,255]];s=c(s);for(var i=1;i<a.length;i++)if(s<=a[i][0]){var p=a[i-1],q=a[i],t=(s-p[0])/(q[0]-p[0]);return'rgb('+[1,2,3].map(function(k){return Math.round(p[k]+(q[k]-p[k])*t)}).join(',')+')'}return'rgb(237,92,255)'}function speak(t){try{speechSynthesis.cancel();var u=new SpeechSynthesisUtterance(t);u.rate=.96;u.pitch=1.02;speechSynthesis.speak(u)}catch(e){}}function addN(s,x){if(s.querySelector('.nitro-naya'))return;var b=document.createElement('div');b.className='nitro-naya';b.innerHTML='<img src="'+NAYA+'" alt="Naya, your AI guide"><div class="nitro-naya-copy"><b>Naya · Your guide</b><span>Hi. I’ve looked at your results. This isn’t your judgment. It’s your map.</span></div><button type="button">Listen</button>';b.querySelector('button').onclick=function(){speak(b.querySelector('span').textContent)};s.insertBefore(b,s.firstElementChild)}function radar(s,x){if(s.querySelector('.nitro-radar-wrap'))return;var z=d(x);if(z.length<5)return;var cc=215,rr=145,p=[];for(var i=0;i<5;i++){var a=-Math.PI/2+i*Math.PI*2/5,q=rr*z[i].score/100;p.push([cc+Math.cos(a)*q,cc+Math.sin(a)*q])}var rings='',axes='',labs='';for(var k=1;k<5;k++){var q=rr*k/4,v=[];for(var j=0;j<5;j++){var a=-Math.PI/2+j*Math.PI*2/5;v.push((cc+Math.cos(a)*q)+','+(cc+Math.sin(a)*q))}rings+='<polygon points="'+v.join(' ')+'" fill="none" stroke="rgba(255,255,255,.12)"/>'}for(var j=0;j<5;j++){var a=-Math.PI/2+j*Math.PI*2/5;axes+='<line x1="215" y1="215" x2="'+(cc+Math.cos(a)*rr)+'" y2="'+(cc+Math.sin(a)*rr)+'" stroke="rgba(255,255,255,.10)"/>';labs+='<text x="'+(cc+Math.cos(a)*(rr+30))+'" y="'+(cc+Math.sin(a)*(rr+30))+'" text-anchor="middle" dominant-baseline="middle" fill="rgba(255,255,255,.72)" font-size="10" font-weight="800">'+z[j].name+'</text>'}var svg='<svg viewBox="0 0 430 430" role="img" aria-label="Your five-dimension AI capability fingerprint"><defs><linearGradient id="nitroFill" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#38d7c0" stop-opacity=".58"/><stop offset="1" stop-color="#ed5cff" stop-opacity=".34"/></linearGradient></defs>'+rings+axes+'<polygon points="'+p.join(' ')+'" fill="url(#nitroFill)" stroke="#d8bdff" stroke-width="2"/>'+p.map(function(v,i){return'<circle cx="'+v[0]+'" cy="'+v[1]+'" r="5" fill="'+col(z[i].score)+'" stroke="#fff" stroke-width="2"/>'}).join('')+labs+'</svg>';var w=document.createElement('div');w.className='nitro-radar-wrap';w.innerHTML='<div class="nitro-radar"><div style="position:relative;width:100%;height:100%;display:grid;place-items:center">'+svg+'<div class="nitro-radar-center"><b>'+Math.round(c(x.overallScore))+'</b><span>AI mastery score</span></div></div></div><div class="nitro-score-read"></div>';z.forEach(function(v){var q=document.createElement('div');q.innerHTML='<span>'+v.name+'</span><b>'+Math.round(v.score)+'</b><i style="--w:'+v.score+'%;--c1:'+col(Math.max(0,v.score-10))+';--c2:'+col(v.score)+'"></i>';w.querySelector('.nitro-score-read').appendChild(q)});s.appendChild(w)}function enhance(x){var sections=[].slice.call(root.querySelectorAll('.mx-section,.mx-reading,.mx-wide'));if(!sections.length)sections=[root];sections.slice(0,12).forEach(function(s){s.classList.add('nitro-section');addN(s,x)});var hero=sections[0];if(hero)radar(hero,x);var orb=root.querySelector('.mx-score-orb,.v21-score-orb');if(orb){var cc=col(x.overallScore);orb.style.borderColor=cc;orb.style.boxShadow='inset 0 0 90px '+cc+'55,0 35px 100px rgba(0,0,0,.58),0 0 120px '+cc+'33'}var z=d(x),low=z.slice().sort(function(a,b){return a.score-b.score})[0];if(low){var sec=sections.filter(function(s){return/lever|opportunity/i.test(s.textContent||'')})[0];if(sec&&!sec.querySelector('.nitro-lever')){var q=document.createElement('div');q.className='nitro-lever';q.innerHTML='<div class="nitro-lever-score">'+Math.round(low.score)+'</div><div><b>Your highest-leverage opportunity</b><strong>'+low.name+'</strong><p>Not a weakness. A focused opportunity to create a disproportionate return.</p></div>';sec.appendChild(q)}}[].forEach.call(root.querySelectorAll('.mx-area,.mx-naya-door,.v21-master,.v21-action,.v21-cell'),function(s){s.classList.add('nitro-pathway')});if(!root.querySelector('.nitro-final-naya')){var f=root.querySelector('.mx-cta-final,.v21-cta-final');if(f){var q=document.createElement('div');q.className='nitro-final-naya';q.innerHTML='<img src="'+NAYA+'" alt="Naya"><div><h3>Let’s keep going.</h3><p>I know where you are. Now let’s turn your strongest capability into your next level.</p></div><a href="#">Listen to Naya</a>';q.querySelector('a').onclick=function(e){e.preventDefault();speak('I’ve looked at your results. Let’s turn your strongest capability into your next level.')};f.insertBefore(q,f.firstChild)}}done=true;root.setAttribute('data-nitro-aaa','complete')}function boot(){var n=0;function tick(){n++;var x=r();if(x){enhance(x);if(done)return}if(n<40)setTimeout(tick,100)}tick();if(window.MutationObserver)new MutationObserver(function(){var x=r();if(x&&!root.querySelector('.nitro-radar-wrap'))enhance(x)}).observe(root,{childList:true,subtree:true})}boot()})();</script>'''.replace('__NAYA__',NAYA)

def main():
    if not SOURCE.exists(): raise SystemExit('MISSING AUTHORITATIVE ARTIFACT')
    text=SOURCE.read_text(encoding='utf-8')
    for token in ('window.MAXESS_RESULT','#maxess-results-10'):
        if token not in text: raise SystemExit('SOURCE INTEGRITY FAILED: '+token)
    if not BASELINE.exists(): shutil.copy2(SOURCE,BASELINE)
    block=START+'\n'+CSS+'\n'+JS+'\n'+END
    if START in text:text=re.sub(re.escape(START)+r'.*?'+re.escape(END),block,text,flags=re.S,count=1)
    else:
        pos=text.lower().rfind('</body>')
        text=text[:pos]+block+'\n'+text[pos:] if pos>=0 else text+'\n'+block+'\n'
    SOURCE.write_text(text,encoding='utf-8')
    print('NITRO AAA V3 APPLIED',len(text.encode()),'bytes',len(text.splitlines()),'lines')
if __name__=='__main__':main()
